import {saveFile} from './studio.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const AUDIT_CHECKS=[
 {id:'duplicate',name:'Duplicate',flags:['duplicate_question_after_first','duplicate_question_conflicting_reference'],explanation:'Question text matches another record after character, whitespace and case normalization.'},
 {id:'answer',name:'Reference',flags:['missing_reference_answer','reference_text_label_mismatch'],explanation:'Reference answer is empty, or its text differs from the option identified by a single answer label.'},
 {id:'options',name:'Options',flags:['unparsed_or_missing_options','answer_label_format_review','answer_label_not_in_options'],explanation:'Options cannot be parsed, the answer label needs format review, or the selected label is absent from the options. Multi-select labels are supported.'},
 {id:'encoding',name:'Encoding',flags:['encoding_review'],explanation:'Text contains a replacement character or a private-use Unicode character.'},
 {id:'image',name:'Image cue',flags:['possible_missing_image'],explanation:'A text cue suggests that an image may be needed. This is a review heuristic, not confirmation that information is missing.'}
];
const FLAG_REASONS={missing_reference_answer:'The reference answer is empty.',reference_text_label_mismatch:'The reference text does not match the option identified by its single answer label.',duplicate_question_after_first:'A previous record has the same normalized question text.',duplicate_question_conflicting_reference:'Duplicate normalized questions have different reference answers.',unparsed_or_missing_options:'Fewer than two answer options could be parsed.',answer_label_format_review:'The answer label is empty or uses an unrecognized format.',answer_label_not_in_options:'The answer label refers to an option absent from the parsed choices.',encoding_review:'The text contains a replacement character or private-use Unicode character.',possible_missing_image:'An image-related phrase suggests that visual information may be needed; this requires review.'};
export function auditRows(records,{route='needs_review',check='all',query=''}={}){const text=query.trim().toLowerCase();return records.filter(r=>(route==='all'||r.route===route)&&(check==='all'||AUDIT_CHECKS.find(c=>c.id===check)?.flags.some(f=>r.flags.includes(f)))&&(!text||('row '+r.row).includes(text)||r.sha256.startsWith(text)));}
export function createPublicAudit(api){
 let data,tasks,loading,route='needs_review',check='all',query='',page=0,selected=null;
 const size=12,root=()=>document.querySelector('#main');
 async function load(){if(!loading)loading=Promise.all(['audit','prepared'].map(async file=>{const r=await fetch('data/public-audit/'+file+'.json');if(!r.ok)throw Error('Audit snapshot unavailable.');return r.json()})).then(([a,b])=>{data=a;tasks=b}).catch(e=>{loading=null;throw e});return loading;}
 function filtered(){return auditRows(data.records,{route,check,query});}
 function details(){const record=data.records.find(r=>r.row===selected);if(!record)return '';const applicable=AUDIT_CHECKS.filter(c=>c.flags.some(f=>record.flags.includes(f)));
  return '<aside class="audit-record" aria-label="Selected audit record"><div><span class="eyebrow">SOURCE ROW '+record.row+' · ZERO-BASED</span><h2>'+(applicable.length?'Review this record.':'No structural flag recorded.')+'</h2></div><p>'+(applicable.length?'The following checks triggered review. Medical correctness has not been assessed.':'This record did not trigger the configured structural flags. This is not a medical-quality judgment.')+'</p><ul>'+applicable.map(c=>'<li><strong>'+c.name+'</strong><span>'+esc(record.flags.filter(f=>c.flags.includes(f)).map(f=>FLAG_REASONS[f]||c.explanation).join(' '))+'</span></li>').join('')+'</ul><a class="text-link" href="https://huggingface.co/datasets/OpenMedical/medical-data" target="_blank" rel="noopener">Open source dataset →</a><p class="small-note">Use the row index and pinned revision to locate the source. Original medical text is not copied into this page.</p><details><summary>Record provenance</summary><dl><dt>Dataset revision</dt><dd>'+esc(data.summary.revision)+'</dd><dt>Record SHA-256</dt><dd>'+esc(record.sha256)+'</dd><dt>Method</dt><dd>'+esc(data.method)+' · no RHCA or BTV scoring</dd></dl></details></aside>';
 }
 function draw(){if(location.hash.split('?')[0]!=='#public-audit')return;const s=data.summary,list=filtered(),pages=Math.max(1,Math.ceil(list.length/size));page=Math.min(page,pages-1);const shown=list.slice(page*size,(page+1)*size);if(!shown.some(r=>r.row===selected))selected=shown[0]?.row??null;const percent=s.routes.needs_review/s.rows*100;
  root().innerHTML='<section class="workspace-heading"><div><span class="eyebrow">OPENMEDICAL / MEDICAL-DATA</span><h1>Public Dataset Audit</h1><p>Inspect the source before evaluating behavior.</p></div><button class="button secondary" data-audit="export">Download audit ↓</button></section><div class="pipe-provenance"><span class="pipe-label">STRUCTURAL CHECKS</span><span>Completed snapshot · '+esc(new Date(s.measured_at).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric',timeZone:'America/New_York'}))+' · no model, RHCA or BTV results</span></div><div class="audit-metrics"><div><span>Records</span><strong>'+s.rows.toLocaleString()+'</strong></div><div><span>No structural flags</span><strong>'+s.routes.structural_candidate.toLocaleString()+'</strong></div><div><span>Needs review</span><strong>'+s.routes.needs_review.toLocaleString()+'</strong></div></div><div class="audit-split" role="img" aria-label="'+s.routes.structural_candidate+' records without structural flags; '+s.routes.needs_review+' need review"><span style="width:'+(100-percent)+'%"></span><span style="width:'+percent+'%"></span></div><div class="audit-split-legend"><span>Structural screening, not medical validation.</span><span>'+percent.toFixed(1)+'% flagged for review</span></div><section class="audit-main"><div class="audit-controls"><h2>Record × check</h2><div><label><span class="sr-only">Audit route</span><select id="audit-route">'+[['needs_review','Needs review'],['structural_candidate','No structural flags'],['all','All records']].map(([v,n])=>'<option value="'+v+'" '+(route===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label><span class="sr-only">Audit check</span><select id="audit-check"><option value="all">All checks</option>'+AUDIT_CHECKS.map(c=>'<option value="'+c.id+'" '+(check===c.id?'selected':'')+'>'+c.name+'</option>').join('')+'</select></label><label><span class="sr-only">Find source row or hash</span><input id="audit-query" placeholder="Row or hash" value="'+esc(query)+'"></label><button class="quiet-button" data-audit="search">Find</button></div></div><div class="audit-layout"><div><div class="pipe-table-scroll"><table class="audit-matrix"><caption>Marked cells triggered review. An unmarked cell means no flag, not a verified pass. Flags may overlap.</caption><thead><tr><th scope="col">Source row</th>'+AUDIT_CHECKS.map(c=>'<th scope="col">'+c.name+'</th>').join('')+'</tr></thead><tbody>'+shown.map(r=>'<tr class="'+(r.row===selected?'selected':'')+'"><th scope="row"><button data-audit-row="'+r.row+'">'+String(r.row).padStart(5,'0')+'</button></th>'+AUDIT_CHECKS.map(c=>{const flagged=c.flags.some(f=>r.flags.includes(f));return '<td><button class="audit-flag '+(flagged?'flagged':'')+'" data-audit-row="'+r.row+'" aria-label="Row '+r.row+', '+c.name+': '+(flagged?'review flag':'no flag')+'">'+(flagged?'●':'·')+'</button></td>';}).join('')+'</tr>').join('')+'</tbody></table></div>'+(!shown.length?'<p class="results-empty">No records match these filters.</p>':'')+'<div class="audit-pagination"><span>'+list.length.toLocaleString()+' matching records</span><div><button class="quiet-button" data-audit="previous" '+(page===0?'disabled':'')+'>←</button><span>'+(page+1)+' / '+pages+'</span><button class="quiet-button" data-audit="next" '+(page+1===pages?'disabled':'')+'>→</button></div></div></div><div id="audit-record">'+details()+'</div></div></section><details class="audit-method"><summary>Method & source</summary><p>These are deterministic checks over question, correct_option and correct_answer. They do not use BTV, assign RHCA scores or assess clinical correctness.</p><div class="audit-flag-counts">'+Object.entries(s.flag_counts).map(([flag,n])=>'<div><span>'+esc(flag.replaceAll('_',' '))+'</span><strong>'+n.toLocaleString()+'</strong></div>').join('')+'</div><p>49 raw answer-label values include valid multi-select combinations. Review flags overlap and should not be added together.</p><p>Original-source licenses and citations require separate review. The dataset card reports that only MedQA and MedMCQA test sets were excluded; other sources may contain test data. Per-record original-source attribution is absent from this export.</p><p class="small-note">Revision '+esc(s.revision)+' · Parquet SHA-256 '+esc(s.file_sha256)+'</p></details><details class="audit-prepared"><summary>Prepared tasks · '+tasks.length+' · not run</summary><p>Thirty source cases have four staged user turns each. Model responses, RHCA judgments and BTV results are not available. The staged task design has not been human-reviewed.</p><label><span class="sr-only">Prepared task</span><select id="audit-task">'+tasks.map(t=>'<option value="'+esc(t.id)+'">'+esc(t.id)+' · source row '+t.source.row_index+'</option>').join('')+'</select></label><p id="audit-task-detail">'+esc(tasks[0].id)+' · 4 user turns · source row '+tasks[0].source.row_index+' · not run</p><a class="text-link" href="https://chatgpt.com/library?file_id=libfile_50e81b554b7c8191826872d7af2b04d3&account_id=personal" target="_blank" rel="noopener">Download prepared tasks & scripts →</a></details>';
 }
 document.addEventListener('change',e=>{if(e.target.id==='audit-route'){route=e.target.value;page=0;draw()}if(e.target.id==='audit-check'){check=e.target.value;page=0;draw()}if(e.target.id==='audit-task'){const t=tasks.find(t=>t.id===e.target.value);document.querySelector('#audit-task-detail').textContent=t.id+' · '+t.turns+' user turns · source row '+t.source.row_index+' · not run'}});
 document.addEventListener('keydown',e=>{if(e.target.id==='audit-query'&&e.key==='Enter'){query=e.target.value;page=0;draw()}});
 document.addEventListener('click',e=>{const row=e.target.closest('[data-audit-row]')?.dataset.auditRow;if(row!==undefined){selected=Number(row);draw();return}const action=e.target.closest('[data-audit]')?.dataset.audit;if(!action||!data)return;if(action==='search'){query=document.querySelector('#audit-query').value;page=0;draw()}if(action==='previous'){page--;draw()}if(action==='next'){page++;draw()}if(action==='export')saveFile('public-dataset-audit.json',JSON.stringify(data,null,2),'application/json')});
 return {render:async()=>{await load();draw()}};
}
